  learningTutorialCopy: {
    screen: {title:'读屏学课程',steps:['使用标题和链接导航定位课程。','试用播放器的播放、暂停与进度控件。','键盘操作受阻时，向课程方索取文字稿。']},
    image: {title:'把PPT或图片变成可读文字',steps:['PPT可选中文字时，复制到沟通卡朗读。','图片文字可打开图像阅读，确认单次处理授权。','核对识别结果中的公式、数字和专有名词。']},
    listen: {title:'听读复习',steps:['把自己整理的短文本放进沟通卡。','主动点击朗读，随时停止。','不把朗读结果当作已理解，写下疑问。']},
    chapters: {title:'逐步任务拆章节',steps:['把一章拆成阅读、练习、复盘三个步骤。','学习计划会同步到逐步任务。','做完一项再点完成，不用一次记住全部。']},
    review: {title:'安排复习提醒',steps:['在计划中设置一次学习时间。','页面打开时查看到期提示。','网页关闭后需用手机日历，导出并手动导入。']},
    notes: {title:'笔记与复习卡',steps:['在计划里写下三个关键词和一个疑问。','复习后记录是否能独立解释。','笔记只留本机，随身卡不会带出笔记。']}
  },
