    nanjing: { name: '国开残教南京学院', org: '南京开放大学', scope: '了解南京残疾人学历教育及技能课程方向。', notes: '来源是2024年办学报道，不是招生公告。报名及课程供应须联系学校核对。' },
    cdpee: { name: '中国残疾人就业创业网络服务平台', org: '中国残疾人就业创业网络服务平台', scope: '就业指导、职位信息及就业服务入口。', notes: '官方指南为2024年活动资料。活动已结束，不承诺岗位有效或就业结果。' },
    vocational: { name: '就业创业和职业培训在线服务平台', org: '中国就业培训技术指导中心', scope: '职业指导、技能及创业培训资源。', notes: '官方说明提供音视频方向。单门课程费用、字幕与报名要求需核对。' },
    career: { name: '残疾人就业培训服务说明', org: '中国残疾人联合会', scope: '了解就业培训登记服务，准备向当地残联咨询。', notes: '这是实名统计系统的公开说明，不是报名或学习入口。培训班次请询问当地残联或12385。' },
    smartedu: { name: '国家智慧教育公共服务平台', org: '教育部', scope: '学校教育与终身学习等公共教育资源入口。', notes: '部分页面需JavaScript。字幕与口述影像须逐课核对，不代报名。' },
    mooc: { name: '中国大学MOOC', org: '高等教育出版社与网易', scope: '高校在线课程与学习服务。', notes: '课程、证书及增值服务的费用看原平台。没有确认每门课都有字幕。' },
    xuetang: { name: '学堂在线', org: '清华大学', scope: '高校慕课与在线学习入口。', notes: '入口需JavaScript。选课、费用、字幕与认证条件在原平台核对。' },
    nvda: { name: 'NVDA读屏', org: 'NV Access', scope: 'Windows读屏软件下载与功能介绍。', notes: '软件免费，培训产品另行核对。对课程播放器的兼容性需要实际试用。' },
    zdsr: { name: '争渡读屏', org: '争渡科技', scope: '读屏、键盘帮助与办公软件使用支持。', notes: '公益版功能有限，部分授权收费。仅使用所选版本明确支持的功能。' },
