    exam: { name: '高考合理便利管理规定', org: '教育部、中国残联', scope: '了解高考便利措施、怎么申请和怎么申请重新审查。', notes: '各地申请期限和实际批准内容需另查。其他考试不得直接套用高考安排。' },
