  "accompanimentRequest": "需要陪同或监护",
  "accompanimentScript": "。我需要陪同或监护，请",
  "c3e646bae90a76f7b": "1. 为谁",
  "c1450eed9f9b92e29": "供持证残疾人本地自用。支持六类残疾与多重残疾。",
  "cab57451d555de128": "适合独自坐轮椅去外地看病，或第一次带电动轮椅坐高铁等处境。",
  "cefe04f0c2cd44264": "2. 能做什么",
  "c869a6f01445d5960": "解读辅具商品资料，区分商家宣称、用户反馈和待核实信息。",
  "c8a5b3fff7365a4ad": "按行程与设备生成 A–E 五段清单和随身卡。",
  "c1c4465a99437623e": "用三维试配查看人体与辅具，再按自身尺寸比较款式。",
  "c2de2208e6c16c88d": "3. 不能做什么",
  "c6e88b6d3bcdb3e85": "不含实时无障碍路线规划。",
  "cb0fa6ab7407453d7": "不含站内设施实时状态。",
  "cb4e499005c8413ff": "不代运营商订票与协助申请。",
  "c5757d7f6a9b7242a": "不构成医学适配建议。",
  "c970db6f028a97e8c": "不替代承运方书面确认。",
  "c6b26ae91e62ed86c": "4. 数据从哪来",
  "cfca05ffcbef130d7": "目前接入 ",
  "c83d7f571ffd4c16a": " 个官方规则或服务入口。",
  "c4fa404dc4d124fbf": "铁路 4 个：12306 携带品、重点旅客、订单与投诉入口。",
  "cf4c41ffc14a278e1": "航空 6 个：国航辅具/电池条款、三大航客服、12326。",
  "c739c4f058ed13d76": "城市交通 2 个：上海地铁、杭州地铁；监督渠道 2 个：12328 官方入口与热线办法。",
  "cb8e715e2fcd7f650": "旧版本会保留原文和日期。出发前可以打开官网再看。",
  "c4e75e2780cdc92ac": "5. 你最在意的隐私处理",
  "c0b19ad152664f6be": "资料默认保存在当前浏览器。",
  "c528eb137016ad97d": "不要求上传病历与证件。",
  "cecc49895694b0e50": "可分项删除，也可一键清除全部数据。",
  "c7953313880d9f42c": "6. 版本与更新",
  "cf4f16d00806f7992": "当前版本 ",
  "ceb0d5884569b398e": "。",
  "cc5a3508aadd99027": "最近一次实质改动：",
  "c3b5340343166af94": "第 4 版",
  "cf50bb27ed5de4790": "清单默认全部展开，并加入关于页",
  "c0b63ada0ca51f347": "评委首次进入时看不到完整行动，也无法快速理解产品边界",
  "c9fa90bb0c1e0f6a7": "第 3 版",
  "cb7134d975ec813fe": "清单加入完成度 12/20 和补充资料入口",
  "c4e76af57a6a30dd3": "设备未填时仍像一份完整清单，用户不知道还差什么",
