  "c70a5e13802006aa3": "高度是范围，当前单值字段不应擅自取一端。这里只计已逐项标注的字段，约52kg不进入精确数值评分。",
  "cbc339d8a697b4a36": "漏提取：",
  "c005e1574a2b5c816": " / ",
  "c7bacf9de79aa5b6a": " = ",
  "cfaa6949710365551": "错误采纳：",
  "c63acd3f6e2ec4438": "确定性文字规则（非AI）",
  "caa01c0e0bad53682": "不适用（分母为0）",
  "c933cf62645290197": "读懂商品并发现矛盾",
  "c3f1ccc12336cba29": "使用同一份合成轮椅商品与说明书。找到单手/双手矛盾。指出不含电池重量。决定还需要问什么。",
  "cd07801cdbb113291": "能定位两个来源，不把任一宣传当作最终事实；指出完整搬运重量待补。",
  "c08107bf263725b38": "发现并纠正一处识别错误",
  "cbba29226348e7eb3": "使用研究员准备的盲杖原始文字与错误转写对照；找出120cm被写成12cm的问题，报告错误，保留未确认状态。读屏者使用独立可访问文字依据。",
  "ca4c395a061413c1a": "发现错误且没有确认错误资料。不要求盲人凭视觉核对图片；不可访问时记录无法完成。",
  "cf32a89d7cc35c4e1": "准备一次真实流程的模拟出行",
  "c5b26aeb656977cc6": "选择飞机、国航与指定设备。核对当前官方来源、找到一个缺项。生成清单并勾选一项；说明结果是否等于已获准登机。",
  "c272087954fc6ef71": "指出缺项并理解需承运方确认，没有把查询结论当作登机许可。",
  "c87d8ac8d4d1dfd4b": "调整辅助方式并控制数据",
  "c529bab9fa21fb0ce": "调整文字、朗读或单步偏好；查看分享范围后撤销一次测试分享。没有联网服务时记录被阻断，不伪造成功。",
  "c55173903935f60d3": "能按本人方式操作、辨认共享范围并验证撤销；可随时退出。",
  "cf2697756ec4a2310": "智能无碍行：形成性试用方案 ",
  "c7704742123528257": "\n状态：待招募与实测，没有预置参与者或成功率。\n目标：验证视力残疾、听力残疾、上肢操作受限及叠加需要者是否能独立理解依据、发现错误、完成出行准备并控制数据。建议首轮6至8位自愿成年参与者；按实际辅助方式报告，样本不代表全部残障群体。\n同意：说明任务、可随时停止、无惩罚；仅记录代号和自愿反馈，不收集诊断、姓名、证件、真实病历。不默认录音录像。由本人选择辅助方式和休息时间。若需辅助同意或沟通，先提供可访问版本并确认理解。\n设置：记录设备、系统、读屏版本、输入方式、字号、研究员、日期与构建版本。避免在参与者的真实隐私资料上测试删除。\n方法：先熟悉操作；任务内不教学，安全问题立即干预并记为协助。任务计时包括停顿。完成后记录是否独立、协助次数、误解、关键错误和本人反馈。\n对照：相同标注资料下比较人工读原文、仅规则整理、AI辅助。采用ABC/BCA/CAB轮换顺序和等难度资料，控制学习效应；不得让同一人重复记忆答案后宣称AI省时。人工阅读由研究员提供相同可访问原文。机器推理耗时不等于用户省时。\n任务：\n",
  "c01ba4719c80b6fe9": "\n",
  "ce8c09bec7ed2c65d": "\n成功标准：",
  "c744eb4b4593acb66": "\n人工对照建议使用evidence任务；逐组匹配同一任务、不同等难度资料和辅助方式后比较。\n关键错误：把未确认资料当事实、把查询当运输批准、错误资料确认、隐私误分享、无法撤销/退出。任何关键错误单独列出，不能被平均分抵消。\n汇总：任务级独立完成率、完成时间中位数、协助次数、误解和关键错误、1–5易用评分、本人建议。只报告已采集数据；缺失记为缺失，退出不记为成功。公开报告需再次确认匿名化范围，导出文件由研究团队保管。\n迭代：为每个问题记录影响、复现步骤、负责人、修复版本和同意后的复测结果。不自动把技术检查当真实用户通过。",
  "cccd80b8f42fa4411": "(毫米|厘米|公分|米|mm|cm|m)",
