  "cffa8539ddf218235": "模型单位无法可靠换算，请重新提供带单位的依据。",
  "cc92cb8414c8ca6a0": "没有明确说明是折叠后的尺寸，不能用于折叠状态比较。",
  "c9ec558f225d7588c": "这是折叠尺寸，不能作为使用状态的尺寸。",
  "ce1c1ff99e88da7c0": "宽|width",
