  "c902a6f2434ba3d47": "数值与引用中的尺寸不一致。",
  "cc9639fe2278578e2": "([（(]?\\d+(?:\\.\\d+)?(?:\\s*[-~～–至]\\s*\\d+(?:\\.\\d+)?)?[）)]?)",
  "cbbdc6384780a643b": "尺寸顺序含重复轴，不能采用。",
