  "c145b3a18c8fa27b0": "数值与原文明示的尺寸顺序不一致。",
  "c51ad9d96785e4834": "引用缺少明确尺寸单位或长宽高顺序，不能自动采用。",
  "c3c1d2739fbaa4a92": "重量数值、单位或整机／电池口径与引用不一致。",
