  "c968dd036cbb1eb2b": "高度",
  "cbc6659e2e05b98e7": "门净宽",
  "c6fd9e54a00163278": "承重",
  "cc4c1577a9111e43e": "超出本人填写的可用值。需服务方实测并安排替代设备交运或接驳。不能直接判定适配",
  "c19cb2be697ccc655": "本地规则出行提醒；非实时承运许可",
  "cc48d15561c0581a7": " 资料补齐前，先凭已有设备资料预核对受理与通行条件：",
  "cbd3133b5963e34f0": " 设备资料为",
  "c5b85060549de070e": "，尚需测量的数据可以先怎样核对空间、接应与办理要求？",
  "c262904438c46421f": "办理时说明出发日期",
  "c283d5dd6f0e936ed": "先核对计划出发日期。",
  "cdcdf45b36ecbbe12": "出发地点",
  "c135bdd7537811810": "到达地点",
  "c12872b9721b77e49": "出发日期",
