  "c86c7cbd68d5cb932": "后如需地铁接驳，拨",
  "ccf5efbc50ec3a647": "核对无台阶入口、渡板与换乘接应；当天是否可用须落实，不把电话咨询当作预约成功。",
  "cab77ae1e5e31e957": "到达后需要地铁接驳，请确认接应地点和受理方式。",
