  "c6acafe7b9ff302a3": "，请说明拒绝依据、可补正事项及今天可执行的替代方案。",
  "cc1ca81ccf9dd3a96": "需进一步协调时拨",
  "c7d67721b2f4cf451": "。先找现场负责人，仍未解决联系",
  "c8ce2ed4aba170805": "12328不代替铁路客服。",
  "c3d1146e823665f22": "先找实际航司，12326不代办预约。",
  "ca4c62cfd9f16f631": "12328可受理或转办城市客运等服务问题，不代办车辆预约。",
