  "c9499b137aa62236d": "发生无障碍服务问题，请记录诉求并告知现场解决途径和受理编号。",
  "cb64d3371052d58f0": "核对本票种退改条件",
  "cebb397a37390a766": "。打开原购票渠道订单或到",
  "cc7a92e7fbccee4c0": "服务柜台，先核对退改时限、费用及证明；因设备安排未能成行时先保存客运记录，不默认可免费退改。",
