  "c7711e5c4f0770633": "请填写折叠或实际运输状态的长、宽、高和重量；不能只凭设备名称判断是否装得下。",
  "cb2311615e5e20ac9": "测量折叠后外廓，并核对车门、升降设备或货舱门的净尺寸及承重。",
