  "cdb80bfa3971dfd45": "民航局相关提示",
  "cad31ef3df0ece638": "设备托运；电池处理按承运方要求",
  "c43524f4d909be95f": "电动轮椅 / 代步车不能作为普通随身物品进入客舱；需申请托运并确认电池和货舱装载条件。",
  "c99970b59003a84ad": "已核对国航服务方案：电动轮椅及电动代步工具需托运。不得带入客舱。此要求仅适用所选国航范围。",
  "c0375191604d594a2": "航空公司和机型未确定时，没有统一的轮椅货舱尺寸上限；请索取该机型货舱门及装载尺寸。",
  "ce7a57a77019359a6": "购买机票前向实际承运航空公司申请辅助设备运输与登机协助。",
  "c133ea72731df4e2c": "所选国航条款：",
  "ca020c6d65506f9be": "双电池驱动时每块",
  "c1f21190fc40b04e5": "拆下的单块",
  "c27f9547cb82db7f7": "锂电池不超过 ",
  "c5a6f1563adbd6658": " Wh；当前每块 ",
  "c97985eaa56b5d7f2": " Wh。",
  "ca0c85071b61c1b05": "当前可拆锂电池 ",
  "caef6e506e7775ae6": " Wh 超出所选国航条件 ",
  "cf9ae0887db3a52f8": " Wh，不能按这组资料办理。",
  "c35d7679a40a03176": "补充电池化学类型、每块 Wh、数量及是否可拆；固定电池与可拆电池规则不同，不能一概套用 300 Wh。",
  "cf3c9f042db834e94": "折叠尺寸满足时可申请客舱存放，否则托运",
  "ca84099a5f4091cbd": "手动轮椅通常需安排托运；可折叠小型轮椅能否放入客舱须确认尺寸、存放位置及承运方许可。",
  "c26c72a73c5afa365": "所选国航条款中的客舱折叠轮椅尺寸：33 × 91 × 106 cm，还需能安全放入行李架或前排座椅下；此数值不是通用托运上限。",
  "c99e47d2fd3f90385": "已填折叠尺寸通过所选国航条款尺寸比较；仍需确认可用存放位置。",
  "cd5ed423e29091ea6": "当前尺寸或折叠状态不满足所选国航客舱条件；应联系航空公司安排托运。",
  "c4f5b719012aa63df": "客舱尺寸不符合；联系国航安排托运",
  "c5efa5db93b53cc33": "先选实际承运航空公司；客舱存放尺寸与托运装载尺寸应分别核对。",
  "c184becff140d2be6": "折叠存放或申请托运",
  "c285f50fd23cb20de": "助行器等大型辅具需核对折叠尺寸及安全存放位置。超出客舱存放条件时申请托运。",
  "cc69a4f1ef96f4cdf": "小型电子辅具也需安检；备用锂电池应防短路并按承运方要求随身携带。",
  "c0b3c33807ac970a8": "电子或医疗设备需核对电池规格；机上使用还须另行向航空公司确认。",
  "c5035936abcdf9f0c": "能带上飞机和能在机上使用是两回事。请提前确认型号、电池和机上使用安排。",
  "cc4b29d4fa0ec6b9e": "提供设备型号和说明书，单独询问机上使用条件；制氧机与氧气瓶不可混同。",
  "c33bbfe50b6a462d3": "中国铁路 12306：携带品规定",
  "cc5c4c6dc2db6b232": "12306 携带品规定",
  "c9b34f323658f1df6": "普通携带品：长宽高之和不超过 ",
  "c640c5a3da1313051": " cm，每件重量不超过 20 kg；旅行代步所用折叠轮椅适用例外，不直接套用普通行李限额。",
  "ccb516c4c136568df": "电动代步车不自动按电动轮椅例外处理；需确认硬质包装、携带品规格和站内使用要求。",
  "cbd07c326040552e4": "提供具体车型向车站确认，不能把电动代步车与轮椅当作同一类别。",
  "cf9c8e984559efd02": "联系 12306 / 出发站预约重点旅客服务。确认车门、轮椅空间和上下车协助。",
  "cc00f4f1b2f2ab3c5": "当前资料超过普通携带品尺寸或重量条件；需向铁路确认是否适用辅具例外或另行托运。",
  "c1398e80babb7d36e": "预约可容纳设备的车辆 / 无障碍通道",
  "ce37da83f8713b1fe": "核对携带与使用安排",
  "cc7c6bdd8149f5660": "需按城市、线路和车型确认可用空间及协助条件。当前没有全国统一尺寸值。",
  "c1fcd0bad67032c69": "建议预留操作余量，确认坡道承重、车门净宽及轮椅固定位置；这些是通行建议，不是官方统一限值。",
  "cfc87da720091f440": "公交 / 地铁联系当地运营方；出租车或网约车先确认后备厢，必要时预约无障碍车辆。",
  "cad2de78674d678e7": "设备外廓超过你填写的可用空间，当前装载方案不适配；建议折叠、拆卸或更换车辆 / 航班。",
  "cc39b3b7e28251d06": "设备宽度超过你填写的入口净宽，当前通行方案不适配。",
  "c16499ad87434594d": "可用空间由你根据运营方提供的信息填写；通过尺寸比较不等于通过承重、电池或安检。",
