  "cb55e3ce205ce86d2": "设备重量超过你填写的装载限重，当前装载方案不适配。",
  "c85734e3763a77834": "如需本人坐在设备上通过升降设备。应另向运营方核对本人、设备与随行物品的合计承重。",
  "cd401f4363251b6ad": "妥善收纳辅具，到场时主动说明用途并配合安全检查。",
  "c79acb2cc7d069d0d": "缺少运输状态完整长宽高或重量，请补齐后重新检查。",
  "c005e84969633c98a": "补充电池类型、每块 Wh 和数量；未知项不会当成符合要求。",
  "cf86abc6545678ad8": "此出行方式尚无匹配的本地规则，先向实际运营方核实。",
  "c95831da9e011ba7b": "这次没有可参考的有效官方条款。请查看官网或联系实际承运方取得书面回复。已过期的限值不用于判断能否携带。",
